$payload=['job_id'=>$id,'lease'=>$new['lease'],'result'=>['report'=>['examples'=>0,'folder'=>'private/local/path'],'model'=>['game_key'=>'2026-rebuilt','feature_version'=>'robot-rgb-motion-v1','model_id'=>str_repeat('a',64),'heads'=>[],'used_label_ids'=>[],'release_ready'=>true],'benchmark'=>null]];
